evaluation.reference:
Subroutine SortTwo(a As Integer By Reference, b As Integer By Reference)
  If a > b Then
    Define saved As Integer <- a;
    a <- b;
    b <- saved;
  EndIf
EndSubroutine

Algorithm Main
  Define primero, segundo As Integer;
  Read primero;
  Read segundo;
  SortTwo(primero, segundo);
  Write primero, " ", segundo;
EndAlgorithm
